class Solution:
    def minPathCost(self, grid: List[List[int]], moveCost: List[List[int]]) -> int:
        m, n = len(grid), len(grid[0])
        dp = grid[0][:]
        pv = grid[0][:]
        for i in range(1, m):
            ndp = [0] * n
            for j in range(n):
                ndp[j] = grid[i][j] + min(dp[k] + moveCost[pv[k]][j] for k in range(n))
            dp, pv = ndp, grid[i][:]
        return min(dp)

