class Solution {
public:
    int minPathCost(vector<vector<int>>& grid, vector<vector<int>>& moveCost) {
        int m = grid.size(), n = grid[0].size();
        vector<int> dp(grid[0].begin(), grid[0].end()), pv = dp;
        for (int i = 1; i < m; i++) {
            vector<int> ndp(n);
            for (int j = 0; j < n; j++) {
                int best = INT_MAX;
                for (int k = 0; k < n; k++)
                    best = min(best, dp[k] + moveCost[pv[k]][j]);
                ndp[j] = best + grid[i][j];
            }
            dp = ndp; pv = grid[i];
        }
        return *min_element(dp.begin(), dp.end());
    }
};

