class Solution {
    public int minPathCost(int[][] grid, int[][] moveCost) {
        int m = grid.length, n = grid[0].length;
        int[] dp = grid[0].clone(), pv = grid[0].clone();
        for (int i = 1; i < m; i++) {
            int[] ndp = new int[n];
            for (int j = 0; j < n; j++) {
                int best = Integer.MAX_VALUE;
                for (int k = 0; k < n; k++)
                    best = Math.min(best, dp[k] + moveCost[pv[k]][j]);
                ndp[j] = best + grid[i][j];
            }
            dp = ndp; pv = grid[i].clone();
        }
        int ans = Integer.MAX_VALUE;
        for (int v : dp) ans = Math.min(ans, v);
        return ans;
    }
}

