var minPathCost = function(grid, moveCost) {
    const m = grid.length, n = grid[0].length;
    let dp = [...grid[0]], pv = [...grid[0]];
    for (let i = 1; i < m; i++) {
        const ndp = Array(n);
        for (let j = 0; j < n; j++) {
            let best = Infinity;
            for (let k = 0; k < n; k++)
                best = Math.min(best, dp[k] + moveCost[pv[k]][j]);
            ndp[j] = best + grid[i][j];
        }
        dp = ndp; pv = [...grid[i]];
    }
    return Math.min(...dp);
};
